(() => {
  const els=[...document.querySelectorAll('input,button,[role=button],[role=textbox],[aria-label],div[jsname],span')];
  return els.slice(0,300).map((e,i)=>({i, tag:e.tagName, role:e.getAttribute('role'), text:(e.innerText||e.value||e.getAttribute('aria-label')||'').slice(0,120), aria:e.getAttribute('aria-label'), placeholder:e.getAttribute('placeholder'), jsname:e.getAttribute('jsname'), cls:e.className})).filter(x=>x.text||x.aria||x.placeholder).slice(0,200);
})()

(() => {
  const candidates = [...document.querySelectorAll('input, textarea, [contenteditable="true"], [role="textbox"], [aria-label], button, [role="button"]')];
  return candidates.map((e,i)=>({
    i,
    tag:e.tagName,
    role:e.getAttribute('role'),
    aria:e.getAttribute('aria-label'),
    text:(e.innerText||e.value||'').replace(/\s+/g,' ').trim().slice(0,200),
    placeholder:e.getAttribute('placeholder'),
    name:e.getAttribute('name'),
    type:e.getAttribute('type'),
    classes:(typeof e.className==='string'?e.className:'').slice(0,80),
    rect:(()=>{const r=e.getBoundingClientRect(); return {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}})()
  })).filter(x => (x.aria || x.text || x.placeholder || x.name) && x.rect.w>0 && x.rect.h>0).slice(0,120);
})()

(() => {
  const els=[...document.querySelectorAll('input, textarea, [contenteditable="true"], [role="textbox"], button, [role="button"], [role="combobox"], [aria-label]')];
  return els.map((e,i)=>{const r=e.getBoundingClientRect(); return {i,tag:e.tagName,role:e.getAttribute('role'),aria:e.getAttribute('aria-label'),text:(e.innerText||e.value||'').replace(/\s+/g,' ').trim().slice(0,250),placeholder:e.getAttribute('placeholder'),name:e.getAttribute('name'),type:e.getAttribute('type'),rect:{x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}, html:e.outerHTML.slice(0,300)}}).filter(x=>x.rect.w>0&&x.rect.h>0&&(x.text||x.aria||x.placeholder||x.name)).slice(0,200);
})()

(() => {
  const text = document.body.innerText.replace(/\s+/g,' ').trim();
  const visible = [...document.querySelectorAll('button,[role=button],input,[role=textbox],[role=combobox],a,[aria-label]')].map((e,i)=>{
    const r=e.getBoundingClientRect();
    return {
      i,
      tag:e.tagName,
      role:e.getAttribute('role'),
      aria:e.getAttribute('aria-label'),
      text:(e.innerText||e.value||'').replace(/\s+/g,' ').trim().slice(0,300),
      placeholder:e.getAttribute('placeholder'),
      rect:{x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)},
      html:e.outerHTML.slice(0,250)
    };
  }).filter(x=>x.rect.w>0 && x.rect.h>0 && (x.text||x.aria||x.placeholder)).slice(0,200);
  return {url: location.href, title: document.title, bodyText: text.slice(0,5000), visible};
})()

async () => {
  await new Promise(r => setTimeout(r, 5000));
  const text = document.body.innerText.replace(/\s+/g,' ').trim();
  const visible = [...document.querySelectorAll('button,[role=button],input,[role=textbox],[role=combobox],a,[aria-label]')].map((e,i)=>{
    const r=e.getBoundingClientRect();
    return {
      i,
      tag:e.tagName,
      role:e.getAttribute('role'),
      aria:e.getAttribute('aria-label'),
      text:(e.innerText||e.value||'').replace(/\s+/g,' ').trim().slice(0,500),
      placeholder:e.getAttribute('placeholder'),
      rect:{x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}
    };
  }).filter(x=>x.rect.w>0 && x.rect.h>0 && (x.text||x.aria||x.placeholder)).slice(0,250);
  return {url: location.href, title: document.title, bodyText: text.slice(0,12000), visible};
}

async () => {
  await new Promise(r => setTimeout(r, 15000));
  window.scrollTo(0, document.body.scrollHeight);
  await new Promise(r => setTimeout(r, 1000));
  const text = document.body.innerText.replace(/\s+/g,' ').trim();
  const items = [...document.querySelectorAll('div, li, button, [role=button], [role=listitem]')].map((e,i)=>{
    const r=e.getBoundingClientRect();
    const t=(e.innerText||'').replace(/\s+/g,' ').trim();
    return {i, tag:e.tagName, role:e.getAttribute('role'), aria:e.getAttribute('aria-label'), text:t.slice(0,1000), rect:{x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}};
  }).filter(x=>x.rect.w>0 && x.rect.h>0 && x.text).slice(-120);
  return {readyState: document.readyState, url: location.href, title: document.title, bodyText: text.slice(0,20000), items};
}
